inline std::string_view runtimePanelMessageKeyName(RuntimePanelMessageKey key){
    static constexpr std::array<std::string_view,runtimePanelMessageKeyCount> names={{"runtime.panel.invalid_wait","runtime.panel.saved","runtime.panel.save_failed","runtime.panel.short_title","runtime.panel.short_resize","runtime.panel.short_keys","runtime.panel.title_compact","runtime.panel.title_full","runtime.panel.unsaved_suffix",
        "runtime.panel.edit_prompt","runtime.panel.edit_input","runtime.panel.edit_explanation","runtime.panel.edit_keys","runtime.panel.leave_title","runtime.panel.leave_keys","runtime.panel.review_heading","runtime.panel.next_start_review","runtime.panel.no_changes","runtime.panel.scope","runtime.panel.future_cli","runtime.panel.untouched","runtime.panel.no_session","runtime.panel.activation_notice","runtime.panel.zero_wait","runtime.panel.collection_off","runtime.panel.collection_on","runtime.panel.footer_edit","runtime.panel.footer_review","runtime.panel.footer_browse","runtime.panel.local_defaults"}};
    const auto index=static_cast<std::size_t>(key);return index<names.size()?names[index]:std::string_view{};
}
inline LocalizedMessage runtimePanelMessage(std::string_view language,RuntimePanelMessageKey key){
    const auto index=static_cast<std::size_t>(key);if(index>=runtimePanelMessageKeyCount)return {};
    const auto &source=runtimePanelLocalePacks()[0];const auto *selected=&source;for(const auto &pack:runtimePanelLocalePacks())if(pack.id==language){selected=&pack;break;}
    if(selected->id!=language||!validTemplateTranslation(source.messages[index],selected->messages[index]))return {source.messages[index],source.id,source.review,true,false};
    return {selected->messages[index],selected->id,selected->review,false,selected->rtl};
}
inline std::string runtimePanelEnglish(RuntimePanelMessageKey key){
    const auto text=runtimePanelMessage("en",key).text;return text.find('{')==text.npos?std::string(text):std::string{};
}
inline std::string runtimePanelEnglishInput(const std::string &input){
    if(input.size()>16||!std::all_of(input.begin(),input.end(),[](unsigned char c){return c>=32&&c<=126;}))return {};
    const auto text=runtimePanelMessage("en",RuntimePanelMessageKey::EditInput).text;const auto at=text.find("{input}");
    return at==text.npos?std::string{}:std::string(text.substr(0,at))+input+std::string(text.substr(at+7));
}
